func RenderImpactDigest(baseline, candidate Profile) string {
  delta := computeDelta(baseline, candidate)
  // include p50/p95 deltas and per-1M-token cost estimate
  return fmt.Sprintf("p50: %+0.2fms (\\%+0.2f), p95: %+0.2fms...", delta.P50, delta.P50Pct, delta.P95)
}

